CREATE DATABASE IF NOT EXISTS cedera;
USE cedera;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_log,approval_requests,discrepancies,bordereau_rows,bordereaux,layer_erosion,recoveries,event_losses,loss_events,cessions,policies,treaty_exclusions,treaty_clauses,treaty_documents,treaty_terms,compliance_obligations,treaties;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE treaties (treaty_ref VARCHAR(50) PRIMARY KEY,treaty_name TEXT NOT NULL,treaty_type VARCHAR(30) NOT NULL,class_of_business VARCHAR(100) NOT NULL,cedent_name TEXT NOT NULL,reinsurer_name TEXT NOT NULL,reinsurer_share_pct DECIMAL(5,2) NOT NULL,broker_name TEXT,inception_date DATE NOT NULL,expiry_date DATE NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE treaty_terms (term_ref VARCHAR(50) PRIMARY KEY,treaty_ref VARCHAR(50) NOT NULL,layer_number INT,cession_percentage DECIMAL(7,4),retention_percentage DECIMAL(7,4),retention_amount DECIMAL(18,2),number_of_lines INT,attachment_point DECIMAL(18,2),layer_limit DECIMAL(18,2),event_limit DECIMAL(18,2) NOT NULL,aggregate_limit DECIMAL(18,2),max_cession_any_one_risk DECIMAL(18,2),reinstatements INT,ceding_commission_pct DECIMAL(7,4),profit_commission_pct DECIMAL(7,4),profit_commission_mgmt_expense_pct DECIMAL(7,4),deposit_premium DECIMAL(18,2),minimum_premium DECIMAL(18,2),rate_on_line_pct DECIMAL(7,4),currency VARCHAR(3) NOT NULL,UNIQUE(treaty_ref,layer_number),FOREIGN KEY(treaty_ref) REFERENCES treaties(treaty_ref)) ENGINE=InnoDB;
CREATE TABLE treaty_documents (document_id BIGINT AUTO_INCREMENT PRIMARY KEY,treaty_ref VARCHAR(50) NOT NULL,document_name VARCHAR(500) NOT NULL,document_type VARCHAR(50),storage_uri TEXT,version VARCHAR(50),effective_date DATE,FOREIGN KEY(treaty_ref) REFERENCES treaties(treaty_ref)) ENGINE=InnoDB;
CREATE TABLE treaty_clauses (clause_id BIGINT AUTO_INCREMENT PRIMARY KEY,treaty_ref VARCHAR(50) NOT NULL,document_id BIGINT,clause_ref VARCHAR(100) NOT NULL,clause_title TEXT,clause_text LONGTEXT NOT NULL,page_number INT,UNIQUE(treaty_ref,clause_ref),FOREIGN KEY(treaty_ref) REFERENCES treaties(treaty_ref),FOREIGN KEY(document_id) REFERENCES treaty_documents(document_id)) ENGINE=InnoDB;
CREATE TABLE treaty_exclusions (exclusion_id BIGINT AUTO_INCREMENT PRIMARY KEY,treaty_ref VARCHAR(50) NOT NULL,clause_ref VARCHAR(100),exclusion_name VARCHAR(500) NOT NULL,description TEXT,FOREIGN KEY(treaty_ref) REFERENCES treaties(treaty_ref)) ENGINE=InnoDB;
CREATE TABLE policies (policy_ref VARCHAR(50) PRIMARY KEY,insured_name TEXT NOT NULL,class_of_business VARCHAR(100) NOT NULL,sum_insured DECIMAL(18,2) NOT NULL,gross_premium DECIMAL(18,2) NOT NULL,currency VARCHAR(3) NOT NULL,inception_date DATE NOT NULL,expiry_date DATE NOT NULL,location TEXT NOT NULL,peril TEXT NOT NULL,treaty_ref VARCHAR(50) NOT NULL,FOREIGN KEY(treaty_ref) REFERENCES treaties(treaty_ref)) ENGINE=InnoDB;
CREATE TABLE cessions (cession_ref VARCHAR(50) PRIMARY KEY,treaty_ref VARCHAR(50) NOT NULL,policy_ref VARCHAR(50) NOT NULL,sum_insured DECIMAL(18,2) NOT NULL,gross_premium DECIMAL(18,2) NOT NULL,ceded_sum_insured DECIMAL(18,2) NOT NULL,retained_sum_insured DECIMAL(18,2) NOT NULL,cession_percentage DECIMAL(7,4) NOT NULL,ceded_premium DECIMAL(18,2) NOT NULL,ceding_commission_pct DECIMAL(7,4) NOT NULL,ceding_commission DECIMAL(18,2) NOT NULL,net_ceded_premium DECIMAL(18,2) NOT NULL,currency VARCHAR(3) NOT NULL,calculation_basis VARCHAR(30) NOT NULL,calculated_at DATE NOT NULL,FOREIGN KEY(treaty_ref) REFERENCES treaties(treaty_ref),FOREIGN KEY(policy_ref) REFERENCES policies(policy_ref)) ENGINE=InnoDB;
CREATE TABLE bordereaux (bordereau_id BIGINT AUTO_INCREMENT PRIMARY KEY,bordereau_name VARCHAR(255) UNIQUE NOT NULL,bordereau_type VARCHAR(30) NOT NULL,reporting_period VARCHAR(50),status VARCHAR(30) DEFAULT 'loaded',uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE bordereau_rows (bordereau_row_id BIGINT AUTO_INCREMENT PRIMARY KEY,bordereau_id BIGINT NOT NULL,row_number INT NOT NULL,row_data JSON NOT NULL,UNIQUE(bordereau_id,row_number),FOREIGN KEY(bordereau_id) REFERENCES bordereaux(bordereau_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE discrepancies (discrepancy_ref VARCHAR(50) PRIMARY KEY,bordereau_id BIGINT,row_number INT NOT NULL,discrepancy_type VARCHAR(100) NOT NULL,expected_value TEXT NOT NULL,reported_value TEXT NOT NULL,severity VARCHAR(20) NOT NULL,description TEXT NOT NULL,FOREIGN KEY(bordereau_id) REFERENCES bordereaux(bordereau_id)) ENGINE=InnoDB;
CREATE TABLE loss_events (event_ref VARCHAR(50) PRIMARY KEY,event_name TEXT NOT NULL,peril VARCHAR(100) NOT NULL,event_date DATE NOT NULL,description TEXT,total_gross_loss DECIMAL(18,2) NOT NULL,total_proportional_recovery DECIMAL(18,2) NOT NULL,total_net_retained_loss DECIMAL(18,2) NOT NULL,total_xol_recovery DECIMAL(18,2) NOT NULL,affected_policy_count INT NOT NULL,cat_programme_ref VARCHAR(50),currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,exclusion_note TEXT,FOREIGN KEY(cat_programme_ref) REFERENCES treaties(treaty_ref)) ENGINE=InnoDB;
CREATE TABLE event_losses (event_loss_ref VARCHAR(50) PRIMARY KEY,event_ref VARCHAR(50) NOT NULL,policy_ref VARCHAR(50) NOT NULL,treaty_ref VARCHAR(50) NOT NULL,gross_loss_amount DECIMAL(18,2) NOT NULL,proportional_recovery DECIMAL(18,2) NOT NULL,net_retained_loss DECIMAL(18,2) NOT NULL,currency VARCHAR(3) NOT NULL,reported_date DATE NOT NULL,FOREIGN KEY(event_ref) REFERENCES loss_events(event_ref),FOREIGN KEY(policy_ref) REFERENCES policies(policy_ref),FOREIGN KEY(treaty_ref) REFERENCES treaties(treaty_ref)) ENGINE=InnoDB;
CREATE TABLE recoveries (recovery_ref VARCHAR(50) PRIMARY KEY,event_ref VARCHAR(50) NOT NULL,treaty_ref VARCHAR(50) NOT NULL,layer_number INT NOT NULL,event_date DATE NOT NULL,gross_loss DECIMAL(18,2) NOT NULL,proportional_recovery DECIMAL(18,2) NOT NULL,net_retained_loss DECIMAL(18,2) NOT NULL,attachment_point DECIMAL(18,2) NOT NULL,layer_limit DECIMAL(18,2) NOT NULL,recoverable_amount DECIMAL(18,2) NOT NULL,reinstatement_premium DECIMAL(18,2) NOT NULL,reinstatements_used_to_date INT NOT NULL,aggregate_remaining_after DECIMAL(18,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(30) NOT NULL,calculation_basis TEXT NOT NULL,FOREIGN KEY(event_ref) REFERENCES loss_events(event_ref),FOREIGN KEY(treaty_ref,layer_number) REFERENCES treaty_terms(treaty_ref,layer_number)) ENGINE=InnoDB;
CREATE TABLE layer_erosion (erosion_ref VARCHAR(50) PRIMARY KEY,treaty_ref VARCHAR(50) NOT NULL,layer_number INT NOT NULL,event_ref VARCHAR(50) NOT NULL,event_date DATE NOT NULL,amount_eroded DECIMAL(18,2) NOT NULL,cumulative_eroded DECIMAL(18,2) NOT NULL,current_limit_remaining DECIMAL(18,2) NOT NULL,aggregate_limit DECIMAL(18,2) NOT NULL,aggregate_remaining DECIMAL(18,2) NOT NULL,reinstatements_allowed INT NOT NULL,reinstatements_used INT NOT NULL,currency VARCHAR(3) NOT NULL,as_at DATE NOT NULL,FOREIGN KEY(treaty_ref,layer_number) REFERENCES treaty_terms(treaty_ref,layer_number),FOREIGN KEY(event_ref) REFERENCES loss_events(event_ref)) ENGINE=InnoDB;
CREATE TABLE compliance_obligations (obligation_ref VARCHAR(50) PRIMARY KEY,treaty_ref VARCHAR(50) NOT NULL,obligation_type TEXT NOT NULL,jurisdiction VARCHAR(100) NOT NULL,frequency VARCHAR(30) NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL,last_filed_date DATE,responsible_party VARCHAR(30) NOT NULL,days_to_due INT NOT NULL,as_at DATE NOT NULL,FOREIGN KEY(treaty_ref) REFERENCES treaties(treaty_ref)) ENGINE=InnoDB;
CREATE TABLE approval_requests (approval_id BIGINT AUTO_INCREMENT PRIMARY KEY,request_type VARCHAR(100) NOT NULL,reference_id VARCHAR(100),requested_by VARCHAR(255),status VARCHAR(30) DEFAULT 'pending',requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,approved_by VARCHAR(255),approved_at TIMESTAMP,reason TEXT) ENGINE=InnoDB;
CREATE TABLE audit_log (audit_id BIGINT AUTO_INCREMENT PRIMARY KEY,entity_type VARCHAR(100) NOT NULL,entity_ref VARCHAR(100),action VARCHAR(100) NOT NULL,actor VARCHAR(255),details JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;

CREATE INDEX idx_terms_treaty ON treaty_terms(treaty_ref); CREATE INDEX idx_policies_treaty ON policies(treaty_ref); CREATE INDEX idx_cessions_policy ON cessions(policy_ref); CREATE INDEX idx_cessions_treaty ON cessions(treaty_ref); CREATE INDEX idx_event_losses_event ON event_losses(event_ref); CREATE INDEX idx_recoveries_event ON recoveries(event_ref); CREATE INDEX idx_erosion_date ON layer_erosion(treaty_ref,layer_number,event_date); CREATE INDEX idx_compliance_due ON compliance_obligations(due_date); CREATE INDEX idx_bordereau_rows ON bordereau_rows(bordereau_id);

SELECT 'treaties' table_name,COUNT(*) row_count FROM treaties UNION ALL SELECT 'treaty_terms',COUNT(*) FROM treaty_terms UNION ALL SELECT 'policies',COUNT(*) FROM policies UNION ALL SELECT 'cessions',COUNT(*) FROM cessions UNION ALL SELECT 'loss_events',COUNT(*) FROM loss_events UNION ALL SELECT 'event_losses',COUNT(*) FROM event_losses UNION ALL SELECT 'recoveries',COUNT(*) FROM recoveries UNION ALL SELECT 'layer_erosion',COUNT(*) FROM layer_erosion UNION ALL SELECT 'compliance_obligations',COUNT(*) FROM compliance_obligations UNION ALL SELECT 'bordereau_rows',COUNT(*) FROM bordereau_rows UNION ALL SELECT 'discrepancies',COUNT(*) FROM discrepancies;
